+export function mapAgentStatus(status: string): CloudSessionStatus | undefined {
+	switch (status) {
+		case "running":
+		case "pending":
+			return "running"
+		case "completed":
+			return "completed"
+		case "failed":
+		case "error":
+			return "failed"
+		case "idle":
+			return "idle"
+		case "cancelled":
+		case "aborted":
+			return "cancelled"
+		default:
+			return undefined
+	}
